// Generated by Gemini
// gen-album-manifest.js
import fs from "fs/promises";
import * as musicMetadata from "music-metadata";
import path from "path";

// --- CONFIGURE THIS ---
// Change these values for each album you want to process
const albumDirectory = "./public/demo/albums/tchaikovsky-the-seasons";
const artist = "Gregor Quendel";
const album = "Beethoven's Greatest Hits";
const albumId = "tchaikovsky-the-seasons";
// ----------------------

async function createManifest() {
  try {
    const files = await fs.readdir(albumDirectory);
    const mp3Files = files
      .filter((file) => file.toLowerCase().endsWith(".mp3"))
      .sort();

    const tracks = [];
    for (const file of mp3Files) {
      const filePath = path.join(albumDirectory, file);
      const metadata = await musicMetadata.parseFile(filePath);

      // Clean up the title from the filename
      const title = path
        .basename(file, ".mp3")
        .replace(/^\d+\s?\.?\s?/, "") // Remove leading numbers like "01."
        .replace(/_/g, " "); // Replace underscores with spaces

      tracks.push({
        id: path
          .basename(file, ".mp3")
          .toLowerCase()
          .replace(/[^a-z0-9]/g, "-"),
        title: metadata.common.title || title, // Prefer tag title, fallback to filename
        durationMs: Math.round(metadata.format.duration * 1000),
      });
    }

    const manifest = {
      id: albumId,
      title: album,
      artist: artist,
      artworkUrl: `/demo/albums/${albumId}/cover.jpg`,
      tracks: tracks,
    };

    console.log(JSON.stringify(manifest, null, 2));
  } catch (error) {
    console.error("Error generating manifest:", error);
  }
}

createManifest();
